import{_ as e,o as a,c as r,ag as l}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"配置Azure Translator","description":"介绍在Mutelink中配置Azure Translator云翻译的步骤，包括创建资源、免费额度、密钥和区域。","frontmatter":{"description":"介绍在Mutelink中配置Azure Translator云翻译的步骤，包括创建资源、免费额度、密钥和区域。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"配置Azure Translator | Mutelink"}],["meta",{"property":"og:description","content":"介绍在Mutelink中配置Azure Translator云翻译的步骤，包括创建资源、免费额度、密钥和区域。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"配置Azure Translator | Mutelink"}],["meta",{"name":"twitter:description","content":"介绍在Mutelink中配置Azure Translator云翻译的步骤，包括创建资源、免费额度、密钥和区域。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}]]},"headers":[],"relativePath":"zh/guide/azure-translator.md","filePath":"zh/guide/azure-translator.md"}'),o={name:"zh/guide/azure-translator.md"};function n(i,t,s,u,d,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="azure-translatorの導入" tabindex="-1">配置Azure Translator <a class="header-anchor" href="#azure-translatorの導入" aria-label="Permalink to &quot;配置Azure Translator {#azure-translatorの導入}&quot;">​</a></h1><p>本页介绍为Mutelink创建Azure Translator（微软云翻译）密钥的方法。F0免费层每月可翻译200万字符。</p><p>使用PLaMo或TranslateGemma本地翻译时无需此设置。可参考<a href="/Mutelink-releases/zh/compare/translation">翻译引擎对比</a>选择。</p><div class="info custom-block"><p class="custom-block-title">开始前须知</p><ul><li>Azure注册需要地址、电话号码及信用卡验证。本流程需要完成注册和认证，开通<strong>即用即付订阅</strong>。仅注册Microsoft账号还不够。</li><li>选择F0免费层时，超出每月200万字符不会收费，而是当月无法继续翻译。</li><li>待翻译文字会发送至Microsoft服务器（<a href="/Mutelink-releases/zh/about/privacy">隐私</a>）。</li><li>Azure门户的界面和名称可能变化。如与本指南不同，请查找名称相近的选项。</li></ul></div><h2 id="_1-azureの従量課金制サブスクリプションを用意する" tabindex="-1">1. 准备Azure即用即付订阅 <a class="header-anchor" href="#_1-azureの従量課金制サブスクリプションを用意する" aria-label="Permalink to &quot;1. 准备Azure即用即付订阅 {#_1-azureの従量課金制サブスクリプションを用意する}&quot;">​</a></h2><ol><li>打开<a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure账号注册页</a>，开始注册即用即付订阅。</li><li>使用Microsoft账号登录，没有账号可现场创建。</li><li>按提示填写地址等注册信息，完成电话和信用卡验证，并登记付款方式。</li><li>在<a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure门户</a>的“订阅”中确认即用即付订阅已创建且处于启用状态。</li><li>如从免费账号开始，请按需通过“升级”转为即用即付。</li></ol><p>已有有效的即用即付订阅时可跳过此步骤。</p><p>订阅的“即用即付”和Translator资源的“定价层”是两项不同设置。下一步将Translator定价层设为<strong>Free F0</strong>。创建其他付费服务或选择Translator付费层会产生相应费用。</p><h2 id="_2-translatorのリソースを作る" tabindex="-1">2. 创建Translator资源 <a class="header-anchor" href="#_2-translatorのリソースを作る" aria-label="Permalink to &quot;2. 创建Translator资源 {#_2-translatorのリソースを作る}&quot;">​</a></h2><ol><li>打开<a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure门户</a>。</li><li>在顶部搜索“Translator”，选择对应服务（日语界面为“翻訳ツール”），点击“创建”。</li><li>按以下内容填写。</li></ol><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>订阅</td><td>你的订阅（只有一个时保留默认值）</td></tr><tr><td>资源组</td><td>点击“新建”，自定名称，如<code>mutelink</code></td></tr><tr><td>区域</td><td>选择附近区域，如<code>Japan East</code>。<strong>稍后在Mutelink中填写此区域</strong></td></tr><tr><td>名称</td><td>用于识别资源的名称，如<code>mutelink-translator-1234</code>。若已被使用，请修改末尾数字等</td></tr><tr><td>定价层</td><td><strong>Free F0</strong>（每月免费200万字符）</td></tr></tbody></table><ol start="4"><li>点击“查看+创建”，确认内容后点击“创建”。</li><li>部署完成后，点击“转到资源”。</li></ol><p>“转到资源”有时会打开资源组而非Translator。此时从列表选择刚创建的Translator。创建后可能尚未显示，请点击“刷新”，再点击出现的Translator名称。</p><div class="tip custom-block"><p class="custom-block-title">无法选择Free F0时</p><p>每个订阅只能创建一个免费层Translator资源。请检查是否留有之前创建的资源。</p></div><h2 id="_3-キーとリージョンを確認する" tabindex="-1">3. 查看密钥和区域 <a class="header-anchor" href="#_3-キーとリージョンを確認する" aria-label="Permalink to &quot;3. 查看密钥和区域 {#_3-キーとリージョンを確認する}&quot;">​</a></h2><ol><li>打开创建的Translator，在左侧选择“密钥和终结点”。若当前位于资源组，先点击列表中的Translator。</li><li>复制“密钥1”（KEY 1）。</li><li>记下“位置/区域”（Location/Region）的值，如<code>japaneast</code>。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要向他人展示密钥</p><p>知道密钥的人可使用你的翻译额度。请避免在直播、屏幕共享或截图中泄露。泄露后可在同一页面重新生成密钥1。</p></div><h2 id="_4-mutelinkに入れる" tabindex="-1">4. 在Mutelink中填写 <a class="header-anchor" href="#_4-mutelinkに入れる" aria-label="Permalink to &quot;4. 在Mutelink中填写 {#_4-mutelinkに入れる}&quot;">​</a></h2><ol><li>打开Mutelink的设置 &gt; 翻译。</li><li>在Azure Translator栏，将密钥1填入“Azure Translator密钥”，将记录的区域字符串（如<code>japaneast</code>）填入“区域”。</li><li>运行翻译测试，确认能够返回译文。</li><li>在翻译引擎优先级中，将Azure Translator放到想使用的顺位。</li></ol><p>密钥仅保存在这台电脑的设置中。</p><h2 id="うまくいかないとき" tabindex="-1">故障排除 <a class="header-anchor" href="#うまくいかないとき" aria-label="Permalink to &quot;故障排除 {#うまくいかないとき}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>检查内容</th></tr></thead><tbody><tr><td>测试提示密钥无效</td><td>检查前后是否有空格，是否误用了非Translator资源的密钥</td></tr><tr><td>测试提示区域错误</td><td>按“位置/区域”原样输入，如<code>japaneast</code>，而不是<code>Japan East</code></td></tr><tr><td>之前可用但突然失败</td><td>检查每月200万字符是否已用完，可在Azure资源的“指标”中查看</td></tr><tr><td>创建后立即失败</td><td>新资源可能需要几分钟才能使用</td></tr></tbody></table><p>Mutelink的设置 &gt; 翻译会显示本机本应用在本月、今天及最近30天翻译的字符数。同一密钥在其他地方的使用量不包含在内。</p><h2 id="やめるとき" tabindex="-1">停止使用时 <a class="header-anchor" href="#やめるとき" aria-label="Permalink to &quot;停止使用时 {#やめるとき}&quot;">​</a></h2><p>在Azure门户中删除创建的资源或整个资源组，并清空Mutelink设置 &gt; 翻译中的密钥。</p><p>注册条件和定价层详情请参阅Microsoft的<a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure账号说明</a>及<a href="https://learn.microsoft.com/ja-jp/azure/ai-services/translator/how-to/create-translator-resource" target="_blank" rel="noreferrer">Translator资源创建指南</a>。</p>',26)])])}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
